import re

from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand

__author__ = "Haili Guo"
__copyright__ = "Copyright (C) 2018, Nokia"
__email__ = "haili.guo@nokia-sbell.com"


class PlanEdit(GenericEMSSIMCommand):
    """Planedit command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, obj=None, attr=None, val=None, runner=None, error_code=None):
        """
        Planedit command.

        :param connection: moler connection to device, terminal when command is executed.
        :param obj: name of object
        :param attr: name of object attribute
        :param attr: new value that will be set
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(PlanEdit, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.obj = obj
        self.attr = attr
        self.val = val
        self.error_code = "" if error_code is None else error_code
        self.ret_required = False

    _re_attr = re.compile(r"\[\d+\]\s*$")
    _re_val = re.compile(r"^\s*\[")

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "plan_edit"
        if self._regex_helper.search_compiled(PlanEdit._re_attr, self.attr):
            if not self._regex_helper.search_compiled(PlanEdit._re_val, self.val):
                self.val = f"[{self.val}]"
        if self.obj and self.attr and self.val:
            cmd = f"{cmd} {self.obj} {self.attr} {self.val}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error_code(line)
            except ParsingDone:
                pass
        return super(PlanEdit, self).on_new_line(line, is_full_line)

    _re_error_code = re.compile(r"(?P<error>ERROR:.*doesn't have attribute)")

    def _parse_error_code(self, line):
        if self._regex_helper.search_compiled(PlanEdit._re_error_code, line):
            self.error_code = "NO_ATTR"
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('error')}"))
            raise ParsingDone


